import json,sys
S,OUT=sys.argv[1],sys.argv[2]
D=json.load(open(S+'/data.json'));K=D['KAORI'];CAUTION=D['KAORI_CAUTION']
Q1={'rest':'ゆるめる時間','shift':'切り替える時間','lift':'上向く時間'};Q2={'flower':'花の香り','citrus':'柑橘の香り','wood':'木とハーブの香り'}
X={ # 手書きの追加情報：由来、合わせやすい香り、向いている人、題名の副題
 'lavender':dict(sub='眠る前のアロマと、はじめての一本',origin='ラベンダーはシソ科の低木で、初夏に紫の穂のような花を咲かせます。精油は、この花と葉の部分から採られます。古くから洗濯や入浴に使われてきた歴史があり、名前の由来はラテン語の「洗う」にあると言われています。',
   pair=['ベルガモット：甘さに爽やかさが加わり、夜のくつろぎ時間に合う組み合わせ','スイートオレンジ：あたたかく親しみやすい香りになり、家族のいる部屋でも使いやすい','サンダルウッド：落ち着きが深まり、静かに過ごしたい夜に'],who='香りに慣れていない人、まず一本だけ持つなら何がいいか迷っている人に。強い個性がないぶん、ほかの香りと合わせやすく、あとから買い足すときにも無駄になりません。'),
 'bergamot':dict(sub='アールグレイの香り・夜にやさしい柑橘',origin='ベルガモットはミカン科の柑橘で、主にイタリア南部で栽培されています。果実は酸味と苦みが強く、そのまま食べることはほとんどありません。精油は果皮から採られ、アールグレイ紅茶の香りづけに使われることで知られています。',
   pair=['ラベンダー：花の甘さが加わり、眠る前の時間に向く定番の組み合わせ','ゼラニウム：華やかさが増し、気持ちを切り替えたい夕方に','サンダルウッド：落ち着いた深みが出て、大人びた香りに'],who='柑橘の香りは好きだけれど、レモンやグレープフルーツでは元気すぎると感じる人に。紅茶のアールグレイが好きな人は、まず気に入る香りです。'),
 'sandalwood':dict(sub='白檀の香りと、静かな夜の過ごしかた',origin='サンダルウッドはビャクダン科の木で、日本では白檀（びゃくだん）の名で知られています。香りは木の芯の部分にあり、お香、線香、扇子、仏像などに古くから使われてきました。成長に長い年月がかかるため、精油は高価なものが多く、産地によって香りの印象も少しずつ違います。',
   pair=['ラベンダー：木の落ち着きに花のやわらかさが加わり、眠る前に','ベルガモット：甘い木の香りに、明るい柑橘が抜け感を足す','イランイラン：濃厚で華やかな、特別な夜の香りに'],who='お寺や和室の香りに落ち着く人、甘いだけの香りは苦手という人に。香りの変化をゆっくり楽しみたい人にも向いています。'),
 'geranium':dict(sub='ローズに似た香りで、気分のゆらぐ日に',origin='精油に使われるゼラニウムは、フウロソウ科テンジクアオイ属の植物で、ローズゼラニウムやニオイゼラニウムと呼ばれることもあります。園芸店で見かけるゼラニウムの仲間ですが、香りは花ではなく葉から採られます。葉に触れると、ばらに似た香りが立ちます。',
   pair=['ラベンダー：やわらかくまとまり、毎日使いやすい香りに','グレープフルーツ：華やかさに軽さが加わり、午後の気分転換に','ベルガモット：上品で明るい、来客前の部屋にも合う香り'],who='ローズの香りは好きだけれど、精油は高くて手が出ないという人に。甘い花の香りに、少しすっきりした感じがほしい人にも合います。'),
 'grapefruit':dict(sub='気分転換のアロマと、朝の使いかた',origin='グレープフルーツはミカン科の柑橘で、精油は果皮を搾って採られます。果物そのままの香りに近く、食べものの香りとしてなじみがあるので、アロマに慣れていない人にも受け入れられやすい一本です。',
   pair=['ペパーミント：すっきり感が強まり、眠気をはらいたい午後に','ゼラニウム：軽さに華やかさが加わり、気分を上げたい朝に','ローズマリー：きりっとした香りになり、作業の前に'],who='甘い香りが苦手な人、部屋の空気をさっと変えたい人に。玄関やキッチンなど、家の中で空気がこもりやすい場所にも使いやすい香りです。'),
 'peppermint':dict(sub='すっきりしたい朝と、集中の前に',origin='ペパーミントはシソ科のハーブで、精油は葉から採られます。すうっとする清涼感は、メントールという成分によるものです。お菓子や歯みがき粉の香りとして身近なので、はじめてでも想像しやすい香りです。',
   pair=['グレープフルーツ：爽やかさが重なり、夏の午後に','ローズマリー：きりっとしたハーブの香りになり、勉強や仕事の前に','ラベンダー：強さがやわらぎ、気分転換のあとに落ち着きたいときに'],who='甘い香りより、はっきりした香りが好きな人に。暑い季節や、乗りものの移動のあとに使いたい人にも向いています。'),
 'ylang-ylang':dict(sub='華やかな花の香りと、自分をもてなす夜',origin='イランイランはバンレイシ科の高木で、東南アジアなどの熱帯で育ちます。垂れ下がるように咲く黄色い花から精油が採られ、香水の材料としても広く使われてきました。名前は、現地の言葉で「花の中の花」を意味すると言われています。',
   pair=['スイートオレンジ：濃い甘さが軽くなり、ぐっと使いやすくなる組み合わせ','サンダルウッド：深みのある、落ち着いた華やかさに','ベルガモット：甘さに明るさが加わり、上品な印象に'],who='香水のような、存在感のある香りが好きな人に。甘い香りが好きでも、まずは1滴だけで試してから量を決めるのがおすすめです。'),
 'sweet-orange':dict(sub='明るい気分になりたい朝と、家族で使える香り',origin='スイートオレンジはミカン科の柑橘で、ふだん食べているオレンジと同じ仲間です。精油は果皮を搾って採られます。採れる量が多いため、精油のなかでは手ごろな値段のものが多く、はじめての柑橘として選ばれてきました。',
   pair=['ラベンダー：あたたかくやさしい香りになり、家族のいるリビングに','イランイラン：濃い花の香りを、軽く明るくしてくれる','ローズマリー：甘さにきりっとした輪郭が加わり、朝の時間に'],who='くせのない香りがほしい人、家族や来客がいる場所で使いたい人に。冬の部屋をあたたかい印象にしたいときにも合います。'),
 'rosemary':dict(sub='朝の机と、取りかかる前の一呼吸',origin='ローズマリーはシソ科の常緑低木で、肉や魚の料理に使うハーブとして知られています。精油は葉や花の部分から採られます。ヨーロッパでは古くから、記憶や学びと結びつけて語られてきた植物です。',
   pair=['スイートオレンジ：きりっとした香りにあたたかさが加わり、使いやすくなる','グレープフルーツ：軽く爽やかな、朝向きの組み合わせ','ペパーミント：ハーブの清涼感が重なり、眠気をはらいたいときに'],who='朝に使う香りを探している人、作業や勉強を始めるきっかけがほしい人に。料理のハーブの香りが好きな人には、なじみやすい香りです。'),
}
PHOTO={'bergamot','grapefruit'}
out={'items':{}}
for key,v in K.items():
    q1,q2=key.split('-');x=X[v['k']];nm=v['jp'];short=nm.split('（')[0]
    cautions=[CAUTION]
    if v['note']: cautions.insert(0,v['note'])
    faq=[{'q':f'{short}の香りは、どんな人に向いていますか','a':x['who']},
         {'q':f'{short}の精油は、肌につけてもいいですか','a':('原液のまま肌につけるのは避けてください。'+('とくに'+short+'は、肌につけて日光に当たると炎症を起こすことがある（光毒性）とされています。' if v['k'] in PHOTO else '')+'この頁では、ディフューザーやハンカチなどで香らせて楽しむ使い方を紹介しています。肌に使いたい場合は、専門家の指導や製品の説明に従ってください。')},
         {'q':f'{short}は、ほかのどの香りと合わせやすいですか','a':'本文の「合わせやすい香り」で、'+'、'.join(p.split('：')[0] for p in x['pair'])+'との組み合わせを紹介しています。最初は1滴ずつ合わせて、好みのつり合いを探してみてください。'}]
    out['items'][v['k']]={
     'title':f'{short}の香りと使い方｜{x["sub"]}',
     'description':f'{short}（{v["en"]}）はどんな香りか、どんな時間に合うか、ディフューザーやハンカチでの使い方、合わせやすい精油、使うときの注意をまとめました。香りの書は、気分と好みから一本を選ぶための、占いではない本です。',
     'h1':f'{nm}の香り：{v["kw"].split("・")[0]}の一本',
     'lead':f'香りの書で「{Q1[q1]}」と「{Q2[q2]}」を選んだ人に届く香りが、{nm}です。'+v['core'].split('。')[0]+'。どんな香りで、どう使うとよいかを、ゆっくり読んでみてください。',
     'sections':[
      {'h2':f'{short}はどんな香り','paras':[v['core'],x['origin']]},
      {'h2':'こんな時間に','paras':[v['scene'],x['who']]},
      {'h2':f'{short}の使いかた','paras':['精油は、数滴で十分に香ります。はじめは少なめに使い、物足りなければ1滴ずつ足していくのがこつです。'],'list':['香らせる：'+v['air'],'手もとで：'+v['carry']]},
      {'h2':'合わせやすい香り','paras':[f'{short}は、ほかの精油と合わせると印象が変わります。よく合うとされる組み合わせを三つ挙げます。'],'list':x['pair']},
      {'h2':'使うときの注意','paras':cautions},
     ],
     'faq':faq}
out['hub']={
 'title':'香りの選び方｜気分と好みで選ぶ9つのアロマ（精油）',
 'description':'ゆるめたい、切り替えたい、上向きたい。いまの気分と、花・柑橘・木とハーブの好みから、合う香りを選ぶための案内です。ラベンダー、ベルガモット、サンダルウッドなど9つの精油の特徴と使い方、はじめての道具、使うときの注意をまとめました。',
 'h1':'香りの書：気分と好みから、いまの一本を選ぶ',
 'lead':'香りの書は、占いではありません。いまほしい時間と、惹かれる香りの系統。この二つから、今夜のあなたに合う精油を一本選ぶための本です。ここでは、選び方の考えかたと、九つの香りの特徴をまとめます。',
 'sections':[
  {'h2':'香りは「ほしい時間」から選ぶ','paras':['精油の種類はとても多く、名前だけを見ても選べません。迷ったときは、香りそのものより先に「いま、どんな時間がほしいか」を決めるのが近道です。香りの書では、三つの時間に分けています。'],
   'list':['ゆるめる時間：休みたい夜、眠る前に。ラベンダー、ベルガモット、サンダルウッド','切り替える時間：気分を変えたい午後や、区切りをつけたいときに。ゼラニウム、グレープフルーツ、ペパーミント','上向く時間：元気ややる気がほしい朝に。イランイラン、スイートオレンジ、ローズマリー']},
  {'h2':'好みは「花・柑橘・木とハーブ」の三つから','paras':['次に、惹かれる香りの系統を選びます。花の香りはやわらかく甘く、柑橘はみずみずしく明るく、木とハーブはすっきりと落ち着いた印象です。どれが正解ということはなく、その日の気分で変わってかまいません。','同じ「ゆるめる時間」でも、花が好きならラベンダー、柑橘が好きならベルガモット、木の香りが好きならサンダルウッド、というように、好みで一本が決まります。']},
  {'h2':'精油とアロマオイルの違い','paras':['お店では「精油（エッセンシャルオイル）」と「アロマオイル」が並んでいることがあります。精油は、植物の花、葉、果皮、木などから採った天然の香りの成分です。一方、アロマオイルやフレグランスオイルと書かれたものには、合成の香料や、ほかのオイルで薄めたものが含まれることがあります。','どちらが良い悪いではありませんが、この本で紹介しているのは精油です。買うときは、ラベルに「精油」または「エッセンシャルオイル」と書かれているか、植物の名前（学名）と原産国が書かれているかを目安にしてください。']},
  {'h2':'はじめての道具','paras':['精油を楽しむのに、高価な道具は必要ありません。いちばん手軽なのは、ティッシュやハンカチに1滴たらす方法です。'],
   'list':['ティッシュ・ハンカチ：1滴たらして、机や枕もとに置く。道具がいらない、いちばん簡単な方法','アロマストーン：素焼きの石に数滴しみこませる。電気も火も使わないので、寝室や机の上に向く','ディフューザー：精油を細かい霧や風で広げる。リビングなど広い部屋に香らせたいときに','マグカップのお湯：お湯に1滴たらして、湯気と一緒に香りを楽しむ（飲まないでください）']},
  {'h2':'使うときの注意','paras':[CAUTION,'柑橘の精油のうち、ベルガモット、グレープフルーツ、レモンなどは、肌につけて日光に当たると炎症を起こすことがある（光毒性）とされています。この本では、肌につけず、香らせて楽しむ使い方だけを紹介しています。','香りの感じ方には個人差があります。気分が悪くなったら、すぐに使うのをやめて、部屋の空気を入れ替えてください。']},
 ],
 'faq':[
  {'q':'香りの書は、占いですか','a':'いいえ、占いではありません。いまほしい時間と、好きな香りの系統という二つの問いから、合いそうな精油を一本選ぶための案内です。結果は、選ぶときの手がかりとして読んでください。'},
  {'q':'はじめて買うなら、どの香りがおすすめですか','a':'迷ったときは、ラベンダーかスイートオレンジが選ばれることの多い香りです。どちらもくせが少なく、ほかの香りとも合わせやすいので、あとから買い足すときにも使えます。'},
  {'q':'精油は、どのくらいの量を使えばいいですか','a':'ティッシュやアロマストーンなら1〜2滴、ディフューザーなら機器の説明に従ってください。香りは数滴で十分に広がります。少なめから始めて、物足りなければ1滴ずつ足すのがこつです。'},
  {'q':'子どもやペットがいる家でも使えますか','a':'小さなお子さんやペットと暮らしている場合は、使う前に医師や獣医師などの専門家に確認してください。使うときは少量にして、精油の瓶は手の届かない場所に保管してください。'},
 ]}
json.dump(out,open(OUT,'w'),ensure_ascii=False,indent=1)
for k,v in out['items'].items(): print(k,len(v['title']),sum(len(p) for s in v['sections'] for p in s['paras']+s.get('list',[])))
